#!/usr/bin/env python3
# NOTICE: substantially generated by an LLM coding system.

"""Build cook-county-home-sales-2025.csv from Cook County Assessor open data.

Fetches 2025 residential sales, then joins city/ZIP, geography, and building
characteristics onto each parcel. Identifying fields (PIN, street address,
document number, buyer and seller names) are never requested; see the README.
"""

from pathlib import Path
import csv

import requests

BASE = Path(__file__).resolve().parent
OUT_SALES = BASE / "cook-county-home-sales-2025.csv"

SOCRATA = "https://datacatalog.cookcountyil.gov/resource"
SALES_ID = "wvhk-k5uv"

CLASS_DICT_URL = (
    "https://raw.githubusercontent.com/ccao-data/data-architecture/master/"
    "dbt/seeds/ccao/ccao.class_dict.csv"
)

HEADERS = {"User-Agent": "data-adventures-dataset-script/1.0"}

SALE_DATE_START = "2025-01-01"
SALE_DATE_END = "2026-01-01"

# Assessor property classes that describe an actual dwelling. Other 2xx classes
# (residential land, garages, farm buildings, home improvements) are excluded.
HOME_REPORTING_GROUPS = {"Single-Family", "Multi-Family", "Condominium"}

# The `year` column is stored as text and mixes "2025" and "2025.0".
YEAR = "('2025','2025.0')"

PAGE_SIZE = 25000
PIN_CHUNK = 400

# ~110 m of latitude. Enough to map neighborhood patterns, not enough to single
# out one parcel on a block.
COORD_DECIMALS = 3

# Datasets joined onto each sale by PIN: dataset id, fields, extra filter.
# `pin` is added to every projection by fetch_by_pin.
JOINS = {
    "address": ("3723-97qp", "prop_address_city_name,prop_address_zipcode_1", None),
    "place": (
        "nj4t-kc8j",
        "township_name,cook_municipality_name,chicago_community_area_name,lat,lon",
        None,
    ),
    "building": (
        "x54s-btds",
        "char_yrblt,char_bldg_sf,char_land_sf,char_beds,char_rooms,"
        "char_fbath,char_hbath",
        "card = 1",
    ),
}

# No identifier column: every stable unique key upstream (the county's row_id,
# the PIN, the document number) is also a lookup key into the fully identified
# source records, so none is carried over.
COLUMNS = [
    "sale_date",
    "sale_price",
    "class",
    "class_description",
    "property_group",
    "city",
    "zip_code",
    "township_name",
    "municipality",
    "chicago_community_area",
    "latitude",
    "longitude",
    "year_built",
    "building_sqft",
    "land_sqft",
    "bedrooms",
    "rooms",
    "full_baths",
    "half_baths",
    "deed_type",
    "is_multisale",
    "num_parcels_sale",
    "filter_same_sale_within_365",
    "filter_less_than_10k",
    "filter_deed_type",
]


def get_json(dataset_id, **params):
    resp = requests.get(
        f"{SOCRATA}/{dataset_id}.json", params=params, headers=HEADERS, timeout=120
    )
    resp.raise_for_status()
    return resp.json()


def fetch_class_dict():
    resp = requests.get(CLASS_DICT_URL, headers=HEADERS, timeout=60)
    resp.raise_for_status()
    return {r["class_code"]: r for r in csv.DictReader(resp.text.splitlines())}


def fetch_sales():
    """All 2025 sales in a 200-level class, paged."""
    rows = []
    while True:
        batch = get_json(
            SALES_ID,
            # seller_name, buyer_name, doc_no and row_id are left out of the
            # projection so no identifier is downloaded at any point.
            **{
                "$select": "pin,class,sale_date,sale_price,deed_type,is_multisale,"
                "num_parcels_sale,sale_filter_same_sale_within_365,"
                "sale_filter_less_than_10k,sale_filter_deed_type",
                "$where": f"sale_date >= '{SALE_DATE_START}' "
                f"AND sale_date < '{SALE_DATE_END}' AND starts_with(class, '2')",
                "$order": ":id",
                "$limit": PAGE_SIZE,
                "$offset": len(rows),
            },
        )
        rows.extend(batch)
        if len(batch) < PAGE_SIZE:
            return rows


def fetch_by_pin(dataset_id, select, where, pins):
    """Fetch one 2025 row per PIN from a PIN-keyed dataset, in chunks."""
    pins = sorted(pins)
    out = {}
    for i in range(0, len(pins), PIN_CHUNK):
        chunk = pins[i : i + PIN_CHUNK]
        clauses = [
            f"year in {YEAR}",
            "pin in (%s)" % ",".join(f"'{p}'" for p in chunk),
        ]
        if where:
            clauses.append(where)
        for r in get_json(
            dataset_id,
            **{
                "$select": f"pin,{select}",
                "$where": " AND ".join(clauses),
                "$limit": PIN_CHUNK * 4,
            },
        ):
            out.setdefault(r["pin"], r)
        print(f"    {min(i + PIN_CHUNK, len(pins))}/{len(pins)} PINs")
    return out


def num(value, decimals=0):
    """Socrata returns numeric columns as strings like '1907.0'."""
    if value in (None, ""):
        return ""
    return f"{float(value):.{decimals}f}"


def boolean(value):
    """The API returns JSON booleans for these columns."""
    if value in (None, ""):
        return ""
    return "TRUE" if value is True else "FALSE"


def main():
    print("Fetching class dictionary...")
    class_dict = fetch_class_dict()
    home_classes = {
        code
        for code, row in class_dict.items()
        if row["reporting_group"] in HOME_REPORTING_GROUPS
    }
    print(f"  {len(home_classes)} dwelling classes")

    print("Fetching 2025 parcel sales...")
    sales = [s for s in fetch_sales() if s.get("class") in home_classes]
    print(f"  {len(sales)} home sales")

    pins = {s["pin"] for s in sales}
    joined = {}
    for name, (dataset_id, select, where) in JOINS.items():
        print(f"Fetching {name}...")
        joined[name] = fetch_by_pin(dataset_id, select, where, pins)

    rows = []
    for s in sales:
        pin = s["pin"]
        a = joined["address"].get(pin, {})
        p = joined["place"].get(pin, {})
        b = joined["building"].get(pin, {})
        cd = class_dict.get(s.get("class"), {})
        rows.append(
            [
                (s.get("sale_date") or "")[:10],
                num(s.get("sale_price")),
                s.get("class", ""),
                cd.get("class_desc", ""),
                cd.get("reporting_group", ""),
                a.get("prop_address_city_name", ""),
                a.get("prop_address_zipcode_1", ""),
                p.get("township_name", ""),
                p.get("cook_municipality_name", ""),
                p.get("chicago_community_area_name", ""),
                num(p.get("lat"), COORD_DECIMALS),
                num(p.get("lon"), COORD_DECIMALS),
                num(b.get("char_yrblt")),
                num(b.get("char_bldg_sf")),
                num(b.get("char_land_sf")),
                num(b.get("char_beds")),
                num(b.get("char_rooms")),
                num(b.get("char_fbath")),
                num(b.get("char_hbath")),
                s.get("deed_type", ""),
                boolean(s.get("is_multisale")),
                num(s.get("num_parcels_sale")),
                boolean(s.get("sale_filter_same_sale_within_365")),
                boolean(s.get("sale_filter_less_than_10k")),
                boolean(s.get("sale_filter_deed_type")),
            ]
        )

    with open(OUT_SALES, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(COLUMNS)
        # Sorted so a given set of sales always writes in the same order.
        writer.writerows(sorted(rows))
    print(f"  {OUT_SALES.name}: {len(rows)} rows")


if __name__ == "__main__":
    main()
